import {defaults} from './defaults.mjs';
import {mergeContent,extendValidation} from './content-schema.mjs';
export class CmsError extends Error{constructor(message,status=400){super(message);this.status=status;}}
export async function readContent(env){if(!env.DB)return {content:defaults,revision:0};const record=await env.DB.prepare('SELECT content, revision FROM website_content WHERE id = ?').bind(1).first();return record?{content:mergeContent(defaults,JSON.parse(record.content)),revision:record.revision}:{content:defaults,revision:0};}
export function owner(request,env){
 const id=request.headers.get('oai-authenticated-user-id'),email=request.headers.get('oai-authenticated-user-email');
 if(!id||!email)throw new CmsError('Please sign in with the website owner’s ChatGPT account.',401);
 if(!env.CMS_ADMIN_EMAIL||email.toLowerCase()!==env.CMS_ADMIN_EMAIL.toLowerCase())throw new CmsError('This account does not have website editing access.',403);
 return id;
}
const text=(value,max=4000)=>{if(typeof value!=='string'||value.length>max)throw new CmsError('Please check the length and format of your text.');return value.trim();};
const image=(value)=>{const s=text(value,1000);if(!s||/^\/(photos|media)\/[\w./-]+$/.test(s))return s;try{if(new URL(s).protocol==='https:')return s;}catch{}throw new CmsError('Use an uploaded image or a full HTTPS image URL.');};
export function validateContent(raw){
 if(!raw||typeof raw!=='object')throw new CmsError('Invalid page content.');raw=mergeContent(defaults,raw);const out={};
 for(const key of ['brand','email','phone','coverage','office','hours','legalName','licence','privacy','projectsHeading','projectsIntro'])out[key]=text(raw[key],key==='privacy'?12000:1000);
 if(!out.brand||!out.legalName||!out.office||!out.email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(out.email))throw new CmsError('Provide a company name, legal name, office and valid contact email.');
 for(const key of ['home','servicesPage','about','careers','contact']){const page=raw[key];if(!page)throw new CmsError('Missing page content.');out[key]={};for(const k of ['title','description','eyebrow','headline','intro','imageAlt'])out[key][k]=text(page[k],k==='intro'?4000:500);if(!out[key].title||!out[key].headline)throw new CmsError('Each page needs a title and headline.');out[key].image=image(page.image);for(const k of ['sectionTitle','sectionText'])if(k in defaults[key])out[key][k]=text(page[k]);}
 if(!Array.isArray(raw.services)||!raw.services.length||raw.services.length>12)throw new CmsError('Add between one and twelve services.');
 const ids=new Set(),values=new Set();out.services=raw.services.map(s=>{const service={id:text(s.id,80),title:text(s.title,200),value:text(s.value,200),description:text(s.description),summary:text(s.summary??s.description.split(".")[0]+".",1000),image:image(s.image),imageAlt:text(s.imageAlt,300),icon:text(s.icon,30)};if(!/^[a-z0-9-]+$/.test(service.id)||ids.has(service.id)||values.has(service.value)||!service.title||!service.value||!['building','bolt','people','tools'].includes(service.icon))throw new CmsError('Each service needs a unique ID, name and form option.');ids.add(service.id);values.add(service.value);return service;});
 if(!Array.isArray(raw.trust)||raw.trust.length>6)throw new CmsError('Use up to six trust points.');out.trust=raw.trust.map(t=>({title:text(t.title,200),text:text(t.text,1000)}));return extendValidation(raw,out,defaults,message=>{throw new CmsError(message);});
}
export async function saveContent(request,env){const user=owner(request,env);if(!env.DB)throw new CmsError('The website editor is temporarily unavailable. Your changes have not been saved.',503);
 const size=Number(request.headers.get('content-length')||0);if(size>100000)throw new CmsError('Content is too large.',413);const source=await request.text();if(source.length>100000)throw new CmsError('Content is too large.',413);const data=JSON.parse(source);if(!Number.isInteger(data.revision)||data.revision<0)throw new CmsError('Please reload the editor.');const content=validateContent(data.content);const encoded=JSON.stringify(content),date=new Date().toISOString();
 const result=data.revision===0?await env.DB.prepare('INSERT INTO website_content (id, content, revision, updated_at, updated_by) VALUES (?, ?, ?, ?, ?) ON CONFLICT(id) DO NOTHING').bind(1,encoded,1,date,user).run():await env.DB.prepare('UPDATE website_content SET content = ?, revision = revision + 1, updated_at = ?, updated_by = ? WHERE id = ? AND revision = ?').bind(encoded,date,user,1,data.revision).run();
 if(result.meta?.changes!==1)throw new CmsError('Someone saved changes since you opened this page. Reload the editor before saving again.',409);return {content,revision:data.revision+1};
}
export async function uploadImage(request,env){owner(request,env);if(!env.BUCKET)throw new CmsError('Image uploads are temporarily unavailable.',503);const reader=request.body?.getReader();if(!reader)throw new CmsError('Select an image.');const chunks=[];let size=0;while(true){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>5*1024*1024){await reader.cancel();throw new CmsError('Images must be no larger than 5 MB.',413);}chunks.push(value);}const bytes=new Uint8Array(await new Blob(chunks).arrayBuffer());const png=[137,80,78,71,13,10,26,10].every((b,i)=>bytes[i]===b),jpg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255;const type=request.headers.get('content-type');if(!size||!((png&&type==='image/png')||(jpg&&type==='image/jpeg')))throw new CmsError('Use a valid JPG or PNG image.');const key=crypto.randomUUID()+ (png?'.png':'.jpg');await env.BUCKET.put(key,bytes,{httpMetadata:{contentType:type}});return {url:'/media/'+key};}
